    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readNextString() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        const start = offset;
        while (offset < buffer.length && buffer[offset] > 32) {
            offset++;
        }
        return buffer.toString('utf8', start, offset);
    }

    const nStr = readNextString();
    if (!nStr) return;
    const n = parseInt(nStr, 10);
    const m = parseInt(readNextString(), 10);

    const grid = [];
    const queueR = new Int32Array(n * m);
    const queueC = new Int32Array(n * m);
    let head = 0;
    let tail = 0;

    for (let i = 0; i < n; i++) {
        const lineStr = readNextString();
        // Armazenamos como Uint8Array de códigos ASCII: '.' = 46, '#' = 35, 'o' = 111
        const row = new Uint8Array(m);
        for (let j = 0; j < m; j++) {
            const charCode = lineStr.charCodeAt(j);
            row[j] = charCode;
            if (charCode === 111) { // 'o'
                queueR[tail] = i;
                queueC[tail] = j;
                tail++;
            }
        }
        grid.push(row);
    }

    const DOT = 46;
    const HASH = 35;
    const O_CHAR = 111;

    while (head < tail) {
        const r = queueR[head];
        const c = queueC[head];
        head++;

        // Caso 1: água desce verticalmente
        if (r + 1 < n) {
            if (grid[r + 1][c] === DOT) {
                grid[r + 1][c] = O_CHAR;
                queueR[tail] = r + 1;
                queueC[tail] = c;
                tail++;
            } else if (grid[r + 1][c] === HASH) {
                // Caso 2: água escorre para a esquerda e para a direita se há '#' logo abaixo
                if (c - 1 >= 0 && grid[r][c - 1] === DOT) {
                    grid[r][c - 1] = O_CHAR;
                    queueR[tail] = r;
                    queueC[tail] = c - 1;
                    tail++;
                }
                if (c + 1 < m && grid[r][c + 1] === DOT) {
                    grid[r][c + 1] = O_CHAR;
                    queueR[tail] = r;
                    queueC[tail] = c + 1;
                    tail++;
                }
            }
        }
    }

    const outChunks = [];
    for (let i = 0; i < n; i++) {
        outChunks.push(Buffer.from(grid[i]).toString('utf8'));
    }
    process.stdout.write(outChunks.join('\n') + '\n');
}

